#!/usr/bin/env python3import jsonimport osimport globdef load_data(DATA_FILE):    if not os.path.exists(DATA_FILE):        print("Could not find sowing_history.json!")        return []    try:        with open(DATA_FILE, "r") as f:            return json.load(f)    except json.JSONDecodeError:        return []    def get_matching_files(directory, pattern):    '''    Parameters    ----------    directory : string        Folder to look for files in e.g. "data/images/".    pattern : string        String matching pattern e.g. "*.jpg".    Returns    -------    files : list        The files within the directory matching the pattern, in order of oldest to newest.    '''        path = os.path.join(directory, pattern)    files = glob.glob(path)    files.sort()        return files